"""Explain virtual layout, source names and task lifecycle hooks."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1797': ('같은 번호의 물건과 검사표를 서로 다른 선반에 놓으면 시작 위치와 번호만으로 짝을 찾을 수 있어요.', '가상 주소의 평행 배치와 실제 페이지 위치를 구별합니다.', '네 구역을 그리고 데이터, shadow, origin, 일부 모듈 검사 정보를 차례로 적으세요.', ['vmalloc은 커널이 사용할 가상 주소 공간과 관련된 말이에요. 가상 주소는 프로그램이 찾아가는 주소이고 물리 주소는 실제 메모리의 위치를 나타내요. 가상 주소가 나란하다고 실제 메모리 페이지까지 나란할 필요는 없어요.', '고정된 x86 관련 문서는 KMSAN을 위한 vmalloc 영역을 네 구역으로 나눠 설명해요. 첫 4분의 1은 데이터, 둘째는 그 데이터의 shadow, 셋째는 origin에 써요. 넷째의 일부는 커널 모듈의 검사 정보에 사용해요.', 'shadow는 준비 상태표이고 origin은 원인 정보표예요. 모듈은 커널에 추가로 연결하는 코드 묶음이에요. 네 구역을 나눴다는 것은 가상 주소 배치이며 실제 RAM 전체를 같은 비율로 반드시 사용한다는 뜻은 아니에요.', '주소 계산에서는 구역 시작부터 얼마나 떨어졌는지인 offset을 이용해요. 예시로 데이터 시작 1000, shadow 시작 2000, origin 시작 3000을 정해 봐요. 데이터 주소 1012는 시작에서 12만큼 떨어졌으므로 대응 주소는 2012와 3012예요. 실제 커널 주소 대신 이해용 숫자를 썼어요.', '데이터 페이지 배열을 연속 가상 주소에 연결할 때 검사 페이지들도 각자의 연속 가상 공간에 연결해요. 연결을 mapping이라고 해요. 종이에서 데이터 세 칸과 검사표 세 칸을 따로 그린 뒤 같은 순서끼리 연결해 보세요.', '가상 주소가 연속이라는 사실은 흩어진 물리 페이지를 연결해 보여 주는 방식과 양립해요. 모든 단편화가 없어졌다는 뜻은 아니에요. 이 네 구역 배치를 모든 CPU 기종에 공통인 영구 규칙으로 외우지 말고 고정 문서의 대상 범위를 기억하세요.'], [('고정 문서에서 vmalloc의 둘째 구역에는 무엇을 놓나요?', ['일반 프로그램의 스택을 놓아요', '첫 구역 데이터의 shadow 검사표를 놓아요'], '정답은 두 번째예요. 데이터·shadow·origin이 첫째·둘째·셋째 구역에 대응해요. 일반 사용자 프로그램의 스택 배치를 설명하는 수업이 아니에요.'), ('연속 가상 주소로 연결했다면 물리 페이지도 반드시 이웃하나요?', ['아니요. 가상 주소와 물리 위치의 배치는 다를 수 있어요', '네. 모든 물리 페이지가 자동으로 이웃하게 이동해요'], '정답은 첫 번째예요. mapping은 주소를 페이지에 연결하는 관계예요. 가상 공간의 순서를 만들었다고 실제 페이지들을 옮겨 붙였다는 뜻은 아니에요.')]), 'os1798': ('안내서의 이름표와 실제 서랍 이름표가 다르면 둘을 대조해야 해요. 없는 이름을 그대로 따라 쓰면 찾으려는 곳에 도달하지 못해요.', '문서 표기와 실제 파일·필드 선언을 대조하는 방법을 익힙니다.', '문서 표기 nstrumentation.c와 실제 instrumentation.c, 문서 kmsan과 실제 kmsan_ctx를 두 열로 적으세요.', ['문서는 개념을 설명하는 데 유용하지만 오타나 코드와 맞지 않는 표기가 남을 수 있어요. 같은 버전의 문서라도 파일 이름과 구조체 필드는 실제 소스에서 한 번 더 확인해야 해요.', '고정 문서에는 mm/kmsan/nstrumentation.c라는 표기가 있어요. 실제 파일 이름은 첫 i가 있는 mm/kmsan/instrumentation.c예요. instrumentation은 검사에 필요한 코드를 덧붙이는 계측을 뜻해요.', '문서의 문맥 설명에는 current->kmsan.cstate가 나오지만 실제 getter는 current->kmsan_ctx를 사용해요. current는 지금 실행 중인 작업을 뜻해요. 이름이 비슷해도 코드에서 선언된 필드 이름을 맞춰야 해요.', '실제 kmsan_get_context는 작업 문맥이면 current->kmsan_ctx를, 다른 경우에는 CPU별 검사 문맥을 선택해요. __msan_get_context_state는 이렇게 선택된 문맥 안 cstate의 주소를 돌려줘요.', '확인 순서는 문서에서 개념 읽기, 실제 파일 찾기, 함수의 반환식 보기, 사용한 구조체 필드 선언 확인하기예요. 주석을 달 때는 문서가 말한 개념과 실제 코드에서 확인한 이름을 구분해서 적으세요.', '문서와 다른 표기가 있다고 그 이름의 새 파일을 만들어 맞추거나 코드에 없는 필드를 상상하지 마세요. 또한 이 대조는 몇몇 이름을 확인한 것이지 문서와 헤더 전체의 정확성을 모두 검증한 것은 아니에요.'], [('고정 소스에서 현재 작업의 KMSAN 문맥 필드는 무엇인가요?', ['문서에 나온 kmsan이 반드시 실제 선언과 같아요', '실제 getter가 사용하는 kmsan_ctx예요'], '정답은 두 번째예요. 코드의 current->kmsan_ctx를 확인해야 해요. 설명 자료의 이름을 실제 필드 선언이라고 그대로 받아들이지 마세요.'), ('컴파일러 API의 실제 구현 파일 이름은 무엇인가요?', ['mm/kmsan/instrumentation.c예요', 'mm/kmsan/nstrumentation.c예요'], '정답은 첫 번째예요. 실제 경로에는 instrumentation의 첫 i가 있어요. 문서의 빠진 글자와 실제 저장된 파일 이름을 구별하세요.')]), 'os1799': ('새 사람의 기록장을 준비하는 동안 담당자는 자신이 준비 작업 중임을 표시해요. 준비할 대상과 지금 일하는 담당자의 상태는 따로 봐야 해요.', '새 작업의 문맥 준비와 현재 runtime 진입·종료를 구별합니다.', '현재 검사 상태는 0 → 1 → 0으로, 새 task 주소는 내부 생성 함수로 가는 별도 화살표로 그리세요.', ['kmsan_task_create는 새 task의 검사 문맥을 준비하는 내부 함수를 감싸요. task는 커널이 실행 작업을 관리하는 구조를 가리켜요. 여기의 짧은 wrapper 자체가 운영체제의 작업 생성 전체를 구현한 것은 아니에요.', '본문은 세 문장이에요. kmsan_enter_runtime으로 도구 처리에 들어가고 kmsan_internal_task_create(task)를 부른 뒤 kmsan_leave_runtime으로 나와요. 내부 함수가 정상적으로 돌아오는 흐름을 위에서 아래로 따라가세요.', '인자로 받은 task는 준비할 대상이에요. enter_runtime이 바꾸는 상태는 kmsan_get_context가 고른 현재 검사 문맥의 상태예요. 새 task 인자와 현재 실행 쪽의 상태를 같은 상자로 합쳐 그리지 마세요.', '정상 시작 상태가 0이면 enter에서 1이 되고 내부 함수 실행 뒤 leave에서 0이 돼요. 이 wrapper에는 enabled나 in_runtime을 보고 일찍 돌아가는 if문이 없어요. 다른 hook에 있는 조건을 여기에 임의로 추가해서 읽으면 안 돼요.', '파일 첫 주석은 runtime 구간에서 계측된 함수를 부르면 memset 같은 함수의 추적 효과를 건너뛸 수 있다고 설명해요. 자기 작업을 다시 검사하지 않도록 한 조건 때문에 검사표 갱신이 생략될 수 있기 때문이에요.', '실제 데이터를 채웠다는 것과 검사 정보도 맞게 바뀌었다는 것은 별개예요. 그래서 내부 도우미의 호출 조건을 확인해야 해요. 단순히 enter와 leave를 붙였다고 아무 계측 함수나 불러도 같은 결과가 유지되는 것은 아니에요.'], [('task_create wrapper의 실제 순서는 무엇인가요?', ['내부 생성 함수 하나만 불러요', 'runtime 진입 → 내부 생성 → runtime 종료예요'], '정답은 두 번째예요. 세 호출이 그 순서로 있어요. 정상 시작 상태에서 내부 함수는 진입 상태로 실행되고 종료 뒤 원래 상태로 돌아가요.'), ('runtime 구간에서 계측 함수를 아무렇게나 불러도 검사 정보 갱신이 항상 유지되나요?', ['아니요. 자기 작업 검사 억제로 갱신이 생략될 수 있어요', '네. 함수 호출 위치와 관계없이 모든 효과가 같아요'], '정답은 첫 번째예요. 파일 주석이 바로 이 점을 설명해요. 실제 데이터 작업과 검사표 갱신의 실행 조건을 따로 확인해야 해요.')]), 'os1800': ('함수에 전달한 사람의 이름과 지금 일을 마치는 사람은 개념상 구분할 수 있어요. 실제로 누구의 기록을 바꾸는지 호출한 도우미까지 따라가 봐요.', 'task_exit의 조건과 current를 변경하는 실제 대상을 이해합니다.', '입력 task 상자와 current 상자를 따로 그리고 disable_current 화살표를 current의 depth로 연결하세요.', ['kmsan_task_exit는 작업 종료 과정에 쓰이는 KMSAN 도우미예요. task라는 인자를 받지만 이 함수 본문은 그 인자를 직접 사용하지 않아요. 인자가 존재한다는 것만으로 그 대상의 필드를 바꾼다고 추측할 수 없어요.', '먼저 KMSAN이 꺼졌거나 kmsan_in_runtime이 참이면 돌아가요. runtime은 도구 자신의 처리 중인 상태예요. 이 경우 아래의 kmsan_disable_current는 호출하지 않아요.', '조건을 통과하면 kmsan_disable_current를 불러요. 그 도우미의 본문을 따라가면 current->kmsan_ctx.depth를 하나 늘려요. current는 지금 실행 중인 작업이에요. 실제 변경 대상을 helper 안에서 확인하는 이유예요.', '예시로 현재 작업 A의 depth가 0이고 전달한 task 주소가 B를 가리킨다고 놓아 봐요. 조건을 통과한 이 본문이 바꾸는 것은 A의 depth예요. 이것은 인자 사용 여부를 이해하기 위한 모델이지 실제 종료 API에 임의의 다른 작업을 넘겨도 된다는 사용 지침은 아니에요.', '이 함수는 종료 흐름에서 현재 작업의 보고 억제를 요청해요. depth를 늘리는 일은 객체를 메모리에서 해제하는 일이나 runtime 진입과는 달라요. 같은 구조체 안의 숫자라도 뜻과 변경 경로를 구별하세요.', '이 짧은 함수 안에는 enable_current나 새 메모리 해제 코드가 없어요. 종료 전체의 수명과 후속 처리는 호출하는 흐름에서 확인해야 해요. runtime 안인 경우에는 첫 조건에서 끝나므로 이 호출로 depth가 증가하지 않아요.'], [('task_exit가 호출한 도우미는 누구의 depth를 바꾸나요?', ['무조건 인자로 받은 task의 depth예요', 'disable_current가 접근하는 current의 depth예요'], '정답은 두 번째예요. 인자 task는 본문에서 사용되지 않아요. 실제 변경은 helper의 current->kmsan_ctx.depth 증가에서 일어나요.'), ('runtime 안에서 이 task_exit를 호출하면 depth가 증가하나요?', ['아니요. disable_current보다 앞에서 돌아가요', '네. 첫 조건에 관계없이 증가해요'], '정답은 첫 번째예요. kmsan_in_runtime이 참이면 바로 return해요. 따라서 아래 helper에 도달하지 않아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_445.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
